-- 065_maritime_jurisdictions.sql
-- Catálogo OM/STA + vínculos por conta + authority em locais + limites de plano.
-- Seed inicial aplicado de docs/om_sta_rows.csv (fonte canônica).
-- Spec: docs/superpowers/specs/2026-08-03-maritime-jurisdictions-design.md

CREATE TABLE IF NOT EXISTS public.maritime_authorities (
  id INTEGER PRIMARY KEY,
  sigla TEXT NOT NULL UNIQUE,
  nome TEXT NOT NULL,
  logradouro TEXT,
  cidade TEXT,
  uf TEXT,
  cep TEXT,
  telefone TEXT,
  email TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.maritime_authorities IS
  'Catálogo nacional Capitanias/Delegacias/Agências (OM/STA). Read-only para tenants.';

ALTER TABLE public.maritime_authorities ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS maritime_authorities_select ON public.maritime_authorities;
CREATE POLICY maritime_authorities_select ON public.maritime_authorities
  FOR SELECT TO authenticated
  USING (true);

