CREATE TABLE IF NOT EXISTS public.account_jurisdictions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,
  authority_id INTEGER NOT NULL REFERENCES public.maritime_authorities(id) ON DELETE RESTRICT,
  responsible_user_id UUID NOT NULL REFERENCES public.profiles(user_id) ON DELETE RESTRICT,
  email_override TEXT,
  is_default BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT account_jurisdictions_account_authority_unique UNIQUE (account_id, authority_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS account_jurisdictions_one_default_per_account
  ON public.account_jurisdictions (account_id)
  WHERE is_default = true;

CREATE INDEX IF NOT EXISTS idx_account_jurisdictions_account
  ON public.account_jurisdictions (account_id);

COMMENT ON TABLE public.account_jurisdictions IS
  'Jurisdições OM/STA vinculadas à escola + responsável e e-mail override.';

DROP TRIGGER IF EXISTS set_updated_at ON public.account_jurisdictions;
CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.account_jurisdictions
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.account_jurisdictions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS account_jurisdictions_select ON public.account_jurisdictions;
DROP POLICY IF EXISTS account_jurisdictions_insert ON public.account_jurisdictions;
DROP POLICY IF EXISTS account_jurisdictions_update ON public.account_jurisdictions;
DROP POLICY IF EXISTS account_jurisdictions_delete ON public.account_jurisdictions;

CREATE POLICY account_jurisdictions_select ON public.account_jurisdictions
  FOR SELECT USING (is_account_member(account_id, 'viewer'));
CREATE POLICY account_jurisdictions_insert ON public.account_jurisdictions
  FOR INSERT WITH CHECK (is_account_member(account_id, 'admin'));
CREATE POLICY account_jurisdictions_update ON public.account_jurisdictions
  FOR UPDATE USING (is_account_member(account_id, 'admin'));
CREATE POLICY account_jurisdictions_delete ON public.account_jurisdictions
  FOR DELETE USING (is_account_member(account_id, 'admin'));

ALTER TABLE public.class_locations
  ADD COLUMN IF NOT EXISTS authority_id INTEGER REFERENCES public.maritime_authorities(id) ON DELETE RESTRICT;

CREATE INDEX IF NOT EXISTS idx_class_locations_authority
  ON public.class_locations (account_id, authority_id)
  WHERE authority_id IS NOT NULL;

COMMENT ON COLUMN public.class_locations.authority_id IS
  'OM/STA do local; responsável do atestado via account_jurisdictions.';

UPDATE public.plans
SET features = features || jsonb_build_object('max_jurisdictions', 1)
WHERE code = 'starter';

UPDATE public.plans
SET features = features || jsonb_build_object('max_jurisdictions', 3)
WHERE code = 'pro';

UPDATE public.plans
SET features = features || jsonb_build_object('max_jurisdictions', null)
WHERE code = 'business';
